import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min';
import Modal from 'bootstrap/js/dist/modal';
import config from './config'; // Archivo de configuración para la URL base
import axios from 'axios';

const FormularioPago = () => {
  const [previewSrc, setPreviewSrc] = useState('');
  const [fileData, setFileData] = useState(null);
  const [gestionId, setGestionId] = useState(null);
  const [productos, setProductos] = useState([]); // Estado para almacenar las opciones de productos
  const [Id, setId] = useState(null);
  const [formData, setFormData] = useState({
    producto: '',
    fechaPago: '',
    montoQuetzales: 0,
    montoDolares: 0,
    comentarios: '',
  });

  const getToken = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No estás autenticado. Por favor, inicia sesión.',
      }).then(() => {
        localStorage.removeItem('token');
        window.location.href = '/';
      });
      return null;
    }
    return token;
  };

  const fetchProductos = async () => {
    try {
      const token = getToken();
      if (!token) return;

      const response = await axios.post(
        `${config.API_BASE_URL}/drops`,
        {
          valor_int1: gestionId,
          ddl: "LISTADO_CUENTAS"
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
  
      if (response.data) {
        setProductos(response.data); // Asigna las opciones al estado
      } else {
        Swal.fire('Error', 'No se encontraron productos disponibles.', 'error');
      }
    } catch (error) {
      Swal.fire('Error', 'No se pudieron obtener los productos.', 'error');

    }
  };

  const decryptGestionId = async (encryptedValue) => {
    try {
      const token = getToken();
      if (!token) return;

      const response = await axios.post(
        `${config.API_BASE_URL}/decrypt`,
        { encrypted_value: encryptedValue },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      return response.data.decrypted_value;
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error de Desencriptado',
        text: 'No se pudo desencriptar el valor.',
      });
      throw error;
    }
  };

  const handleImageChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreviewSrc(e.target.result);
        setFileData(e.target.result);
      };
      reader.readAsDataURL(file);
    } else {
      setPreviewSrc('');
      setFileData(null);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    // Validaciones
    if (!formData.producto) {
      Swal.fire('Error', 'El campo Producto es obligatorio.', 'error');
      return;
    }

    if (!formData.fechaPago) {
      Swal.fire('Error', 'El campo Fecha de Pago es obligatorio.', 'error');
      return;
    }

    if (!fileData) {
      Swal.fire('Error', 'Debes subir una boleta de pago.', 'error');
      return;
    }

    if (formData.montoQuetzales <= 0 && formData.montoDolares <= 0) {
      Swal.fire('Error', 'Al menos uno de los montos debe ser mayor a 0.', 'error');
      return;
    }

    try {
      const token = getToken();
      if (!token) return;
      
      const payload = {
        id_gestion: gestionId,
        cuenta: formData.producto,
        fecha_pago: formData.fechaPago,
        monto_quetzales: formData.montoQuetzales,
        monto_dolares: formData.montoDolares,
        comentario: formData.comentarios,
        base64: fileData,
        id_usuario: Id, // Esto debería ser dinámico dependiendo del usuario autenticado
      };

      console.log(payload);

      await axios.post(`${config.API_BASE_URL}/ingresa-pagos`, payload, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

                        Swal.fire("Éxito", "Pago registrado correctamente.", "success").then(() => {
                          // Redirigir a la pestaña deseada
                          const urlParams = new URLSearchParams(window.location.search);
                          const encryptedGestionId = urlParams.get('id_gestion');
                          const encryptedId = urlParams.get('id');
                          window.location.href = `./detalle_gestion?id_gestion=${encryptedGestionId}&id=${encryptedId}`;
                        });
    } catch (error) {
      Swal.fire('Error', 'No se pudo registrar el pago.', 'error');
      console.error(error);
    }
  };

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const encryptedGestionId = urlParams.get('id_gestion');
    const encryptedId = urlParams.get('id');

    if (encryptedGestionId) {
      decryptGestionId(encryptedGestionId).then((gestionId) => {
        setGestionId(gestionId);
      });
    } else {
      Swal.fire('Error', 'No se encontrarón los parametros necesarios', 'error');
    }

    if (encryptedId) {
      decryptGestionId(encryptedId).then((Id) => {
        setId(Id);
      });
    } else {
      Swal.fire('Error', 'No se encontrarón los parametros necesarios', 'error');
    }

    //fetchProductos();
  }, []);

  useEffect(() => {
    if (gestionId) {
      fetchProductos();
    }
  }, [gestionId]);

  const handleRegresar = () => {
    window.history.back();
  };

  const handleShowModal = () => {
    const modalElement = document.getElementById('imageModal');
    const modalInstance = new Modal(modalElement);
    modalInstance.show();
  };

  return (
    <div className="container mt-5">
      <div className="card shadow-lg">
        <div className="card-header text-center">
          <h4>Registrar Pago</h4>
          <button type="button" className="btn btn-secondary" onClick={handleRegresar}>
            Regresar
          </button>
        </div>
        <div className="card-body">
          <form id="paymentForm" onSubmit={handleSubmit}>
            <div className="row">
              <div className="col-md-6 mb-3">
                <label htmlFor="producto" className="form-label">
                  Producto
                </label>
                <select
                  className="form-select"
                  id="producto"
                  value={formData.producto}
                  onChange={(e) => setFormData({ ...formData, producto: e.target.value })}
                  required
                >
                  <option value="" disabled>
                    Seleccione una opción
                  </option>
                  {productos.map((producto) => (
                    <option key={producto.VALUE} value={producto.VALUE}>
                      {producto.ITEM}
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-md-6 mb-3">
                <label htmlFor="fechaPago" className="form-label">
                  Fecha de Pago
                </label>
                <input
                  type="date"
                  className="form-control"
                  id="fechaPago"
                  value={formData.fechaPago}
                  onChange={(e) => setFormData({ ...formData, fechaPago: e.target.value })}
                  required
                />
              </div>
            </div>

            <div className="row">
              <div className="col-md-6 mb-3">
                <label htmlFor="montoQuetzales" className="form-label">
                  Monto en Quetzales
                </label>
                <input
                  type="number"
                  className="form-control"
                  id="montoQuetzales"
                  value={formData.montoQuetzales}
                  onChange={(e) => setFormData({ ...formData, montoQuetzales: parseFloat(e.target.value) || 0 })}
                  min="0"
                  step="0.01"
                  placeholder="0.00"
                />
              </div>
              <div className="col-md-6 mb-3">
                <label htmlFor="montoDolares" className="form-label">
                  Monto en Dólares
                </label>
                <input
                  type="number"
                  className="form-control"
                  id="montoDolares"
                  value={formData.montoDolares}
                  onChange={(e) => setFormData({ ...formData, montoDolares: parseFloat(e.target.value) || 0 })}
                  min="0"
                  step="0.01"
                  placeholder="0.00"
                />
              </div>
            </div>

            <div className="mb-3">
              <label htmlFor="comentarios" className="form-label">
                Comentarios
              </label>
              <textarea
                className="form-control"
                id="comentarios"
                rows="3"
                placeholder="Escribe tus comentarios..."
                value={formData.comentarios}
                onChange={(e) => setFormData({ ...formData, comentarios: e.target.value })}
              ></textarea>
            </div>

            <div className="mb-3">
              <label htmlFor="imagen" className="form-label">
                Subir Boleta
              </label>
              <input
                type="file"
                className="form-control"
                id="imagen"
                accept="image/*"
                onChange={handleImageChange}
                required
              />
            </div>

            {previewSrc && (
              <div className="mb-3 text-center">
                <img
                  id="previewImagen"
                  src={previewSrc}
                  alt="Previsualización"
                  className="img-thumbnail"
                  style={{ width: '150px', height: '150px', objectFit: 'cover', cursor: 'pointer' }}
                  onClick={handleShowModal}
                />
              </div>
            )}

            <div className="d-flex justify-content-center">
              <button type="submit" className="btn btn-success">
                Registrar Pago
              </button>
            </div>
          </form>
        </div>
      </div>

      <div className="modal fade" id="imageModal" tabIndex="-1" aria-labelledby="imageModalLabel" aria-hidden="true">
        <div className="modal-dialog modal-dialog-centered">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title" id="imageModalLabel">
                Boleta de pago
              </h5>
              <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div className="modal-body text-center">
              <img id="modalImagen" src={fileData} alt="Vista de imagen" className="img-fluid" />
            </div>
            <div className="modal-footer">
              <a id="downloadBtn" href={fileData} download="boleta.png" className="btn btn-primary">
                Descargar Boleta
              </a>
              <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">
                Cerrar
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FormularioPago;
